// Regenerates src/components/icons.tsx from Lucide icon geometry (ISC license).
// Usage: node scripts/generate-icons.mjs <path-to-react-icons/lu/index.mjs>
// The generated file has no runtime dependency on any icon package.
import { readFile, writeFile } from "node:fs/promises";
const source = await readFile(process.argv[2], "utf8");
const want = {
  AlertTriangle: "TriangleAlert", ArrowLeft: "ArrowLeft", ArrowRight: "ArrowRight", ArrowUpRight: "ArrowUpRight",
  Backpack: "Backpack", BookOpen: "BookOpen", Bookmark: "Bookmark", Calculator: "Calculator", Check: "Check",
  CheckCircle2: "CircleCheck", ChevronLeft: "ChevronLeft", ChevronRight: "ChevronRight", Clock: "Clock",
  Download: "Download", Droplets: "Droplets", ExternalLink: "ExternalLink", FileText: "FileText", Files: "Files",
  HardDrive: "HardDrive", HeartPulse: "HeartPulse", House: "House", LockKeyhole: "LockKeyhole", Menu: "Menu",
  Moon: "Moon", NotebookPen: "NotebookPen", Package: "Package", Pencil: "Pencil", Plus: "Plus", Minus: "Minus",
  Radio: "Radio", RefreshCw: "RefreshCw", Save: "Save", Search: "Search", Settings: "Settings",
  ShieldCheck: "ShieldCheck", ShowerHead: "ShowerHead", Sprout: "Sprout", Sun: "Sun", Thermometer: "Thermometer",
  Trash2: "Trash2", Upload: "Upload", Utensils: "Utensils", WifiOff: "WifiOff", Wrench: "Wrench", Zap: "Zap",
  X: "X", Map: "Map", MapPin: "MapPin", ListChecks: "ListChecks", ShoppingCart: "ShoppingCart", Printer: "Printer",
  ZoomIn: "ZoomIn", ZoomOut: "ZoomOut", LocateFixed: "LocateFixed", Layers: "Layers", CookingPot: "CookingPot",
  Calendar: "Calendar", Flame: "Flame", Info: "Info", Filter: "Filter", RotateCcw: "RotateCcw", Leaf: "Leaf",
  Siren: "Siren", Navigation: "Navigation", CircleSlash: "CircleSlash", Eye: "Eye", Snowflake: "Snowflake",
};
const out = [];
for (const [name, lucide] of Object.entries(want)) {
  const m = new RegExp(`export function Lu${lucide} \\(props\\) \\{\\n  return GenIcon\\((\\{.*\\})\\)\\(props\\);`).exec(source);
  if (!m) throw new Error("Missing Lucide icon " + lucide);
  const svg = JSON.parse(m[1]);
  const nodes = svg.child.map((c) => [c.tag, c.attr]);
  out.push(`export const ${name} = icon(${JSON.stringify(nodes)});`);
}
const header = `// Generated by scripts/generate-icons.mjs from Lucide icon geometry.
// Lucide is ISC licensed (c) Lucide Contributors; see THIRD_PARTY_NOTICES.md.
import { createElement, type SVGProps } from "react";
export type IconProps = Omit<SVGProps<SVGSVGElement>, "children"> & { size?: number | string; strokeWidth?: number | string };
type Node = [string, Record<string, string>];
function icon(nodes: Node[]) {
  return function Icon({ size = 24, strokeWidth = 2, fill = "none", ...rest }: IconProps) {
    return createElement("svg", { xmlns: "http://www.w3.org/2000/svg", width: size, height: size, viewBox: "0 0 24 24", fill, stroke: "currentColor", strokeWidth, strokeLinecap: "round", strokeLinejoin: "round", "aria-hidden": rest["aria-label"] ? undefined : true, focusable: "false", ...rest },
      ...nodes.map(([tag, attr], i) => createElement(tag, { key: i, ...attr })));
  };
}
`;
await writeFile("src/components/icons.tsx", header + out.join("\n") + "\n");
console.log("Generated", out.length, "icons");
